local module = {}

-- @return
-- bool: 是不是IEnumerable
-- string: GenericType
function module.Parse(type: string)
	-- 如果type 类似 IEnumerable<T> ， 则返回 true,T
	local pattern = "IEnumerable<(.+)>"
	local match = string.match(type, pattern)
	if match then
		return true, match
	end
	return false, nil
end
return module
